corpus=Path('eval/corpora/tamagai-2026-10-04')
by_id={t['id']:t for t in gold}
for entry in changes['tasks']:
    task=by_id[entry['task']]
    for field,change in entry['change'].items():
        if isinstance(change,dict) and 'new' in change:
            assert task[field]==change['new'], (task['id'],field)
    print(task['id'],'changes-match',len(task['evidence']),'evidence',len(task['forbidden']),'forbidden')
for task in gold:
    for field in ('evidence','forbidden'):
        for unit in task[field]:
            assert 1<=unit['start']<=unit['end']<=len((corpus/unit['path']).read_text().split('\\n'))
    if task.get('citations'):
        print(task['id'],len(task['citations']['lines']),task['prompt'],task['citations']['scope'])
print('32 tasks: all evidence/forbidden ranges valid')
